import{bV as a,aL as t,u as o,G as r}from"./chunks/framework.DvBUyM1S.js";const g=JSON.parse('{"title":"VSCode插件推荐","description":"","frontmatter":{"title":"VSCode插件推荐","date":"2018-12-28T00:00:00.000Z","tags":["VSCode"],"permalink":"/pages/9c9984/","categories":["VSCode"]},"headers":[],"relativePath":"06.工具/04.VSCode/02.VSCode插件推荐.md","filePath":"06.工具/04.VSCode/02.VSCode插件推荐.md","lastUpdated":1652179217000}'),p={name:"06.工具/04.VSCode/02.VSCode插件推荐.md"};function n(s,e,i,l,d,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="vscode插件推荐" tabindex="-1">VSCode插件推荐 <a class="header-anchor" href="#vscode插件推荐" aria-label="Permalink to &quot;VSCode插件推荐&quot;">​</a></h1><p>工欲善其事必先利其器，从事前端开发已近两年多，休闲时候收录一些觉得常用的插件。</p><h2 id="dom操作" tabindex="-1">DOM操作 <a class="header-anchor" href="#dom操作" aria-label="Permalink to &quot;DOM操作&quot;">​</a></h2><p><strong>Auto Close Tag</strong></p><p>自动闭合HTML标签。</p><p><strong>Auto Rename Tag</strong></p><p>自动重命名标签。</p><p><strong>Autoprefixer</strong></p><p>解析CSS，SCSS，LESS并自动添加前缀。</p><p><img src="https://i.loli.net/2020/07/03/qAked6nT2ZVG8W5.gif" alt="autoprefixer" loading="lazy"></p><h2 id="路径补全" tabindex="-1">路径补全 <a class="header-anchor" href="#路径补全" aria-label="Permalink to &quot;路径补全&quot;">​</a></h2><p><strong>Path Intellisense</strong></p><p>自动补全代码中的路径和文件名。</p><p><strong>Npm Intellisense</strong></p><p>自动完成导入语句中的npm模块。</p><h2 id="代码片段提示" tabindex="-1">代码片段提示 <a class="header-anchor" href="#代码片段提示" aria-label="Permalink to &quot;代码片段提示&quot;">​</a></h2><p><strong>HTML Snippets</strong></p><p>超级实用且初级的 H5代码片段以及提示。</p><p><strong>IntelliSense for CSS class names</strong></p><p>HTML、CSS 类名智能命名提示。</p><p><strong>JavaScript (ES6) code snippets</strong></p><p>提示ES6语法片段。</p><h2 id="美观" tabindex="-1">美观 <a class="header-anchor" href="#美观" aria-label="Permalink to &quot;美观&quot;">​</a></h2><p><strong>vscode-icons</strong></p><p>将项目中不同类型的文件或文件夹通过图标区分出来。</p><p><strong>Guides</strong></p><p>代码的标签对齐线。</p><p><strong>Bracket Pair Colorizer</strong></p><p>让括号拥有独立的颜色，易于区分。</p><h2 id="代码格式化" tabindex="-1">代码格式化 <a class="header-anchor" href="#代码格式化" aria-label="Permalink to &quot;代码格式化&quot;">​</a></h2><p><strong>Prettier - Code formatter</strong></p><p>更漂亮的格式化。</p><p><strong>ESLint</strong></p><p>符合代码风格的代码。</p><h2 id="移动端" tabindex="-1">移动端 <a class="header-anchor" href="#移动端" aria-label="Permalink to &quot;移动端&quot;">​</a></h2><p><strong>px to rem</strong></p><p>如果你有px转rem困惑的话，只需要插件中的基数默认16px，便可一键转换。转换快捷键 <code>option+z</code></p><h2 id="项目管理" tabindex="-1">项目管理 <a class="header-anchor" href="#项目管理" aria-label="Permalink to &quot;项目管理&quot;">​</a></h2><p><strong>Project Manager</strong></p><p>如果你的公司有非常多项目，需要来回切换的话，推荐Project Manage可以让你轻松在项目直接替换，无需在导入项目文件夹打开。</p><p><strong>Bookmarks</strong></p><p>书签，在代码中标记/取消标记位置。</p><p><img src="https://i.loli.net/2020/07/03/Nah4TnfibY9LWgr.jpg" alt="-w589" loading="lazy"></p><h2 id="git" tabindex="-1">Git <a class="header-anchor" href="#git" aria-label="Permalink to &quot;Git&quot;">​</a></h2><p><strong>GitLens</strong></p><p>查看代码作者的身份，无缝地导航和浏览 Git存储库。这就意味着你写的坑，要自己填，严重的话还要被骂。</p><p><strong>Git History</strong></p><p>查看和搜索git日志以及图形和详细信息。</p><h2 id="调试" tabindex="-1">调试 <a class="header-anchor" href="#调试" aria-label="Permalink to &quot;调试&quot;">​</a></h2><p><strong>Code Runner</strong></p><p>支持C, C++, Java, JavaScript, PHP, Python等语言的代码的立即执行。使用方法鼠标右键 <code>Run Code</code>运行该文件。</p><p><strong>Live Server</strong></p><p>类似搭建本地服务器页面，修改直接生效。</p><p>html页面下鼠标右键 <code>open with Live Server</code>打开的页面就是。</p><p><strong>Quokka.js</strong></p><p>Quokka.js 会在你输入时自动计算结果，并在 IDE 中打印结果。</p><h2 id="vue框架" tabindex="-1">Vue框架 <a class="header-anchor" href="#vue框架" aria-label="Permalink to &quot;Vue框架&quot;">​</a></h2><p><strong>vetur</strong></p><ul><li>语法高亮</li><li>片段</li><li>Emmet</li><li>整理/错误检查</li><li>格式化</li><li>自动完成</li><li>调试</li></ul><p><strong>Vue Peek</strong></p><p>快速跳转或浏览作为组件（从模板）或模块导入（从脚本）引用的文件。</p><p><strong>Vue 2 Snippets</strong></p><p>提示Vue 2 的 API，非常方便。</p><h2 id="react框架" tabindex="-1">React框架 <a class="header-anchor" href="#react框架" aria-label="Permalink to &quot;React框架&quot;">​</a></h2><p><strong>React.js code snippets</strong></p><p>用ES6语法去开发React.js应用非常方便。</p><h2 id="提示类" tabindex="-1">提示类 <a class="header-anchor" href="#提示类" aria-label="Permalink to &quot;提示类&quot;">​</a></h2><p>Import Cost</p><p>计算引入包大小，可能引入包大太，就实现一小部分的功能，可能找其它包替代，或者自己实现该功能。</p><h2 id="编程时间管理" tabindex="-1">编程时间管理 <a class="header-anchor" href="#编程时间管理" aria-label="Permalink to &quot;编程时间管理&quot;">​</a></h2><p><strong>WakaTime</strong></p><p>从你的编程时间中生成数据报表。</p><h2 id="主题" tabindex="-1">主题 <a class="header-anchor" href="#主题" aria-label="Permalink to &quot;主题&quot;">​</a></h2><p><strong>One Dark Pro</strong></p><p>Atom中黑暗主题。非常不错，本人一直在用。</p><h2 id="同步vscode配置" tabindex="-1">同步VScode配置 <a class="header-anchor" href="#同步vscode配置" aria-label="Permalink to &quot;同步VScode配置&quot;">​</a></h2><p><strong>Settings Sync</strong></p><p>如果你有多台设备，或者以后不想在重新配置vscode，推荐你用<code>Settings Sync</code>，将vscode上传到gist，以后登录账号就可以一键完成。</p><p>不懂得操作的话，可以看 <a href="https://marketplace.visualstudio.com/items?itemName=Shan.code-settings-sync" target="_blank" rel="noreferrer">官网教程</a></p>',79)])])}const u=a(p,[["render",n]]);export{g as __pageData,u as default};
